/// <summary>
/// Extension class of form data source SalesTable in form SalesTableListPage
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTableListPage, SalesTable))]
internal final class METSalesTableListPageSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// active method on ST datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();

        this.METEnableCustomBtn();
        return ret;
    }

    /// <summary>
    /// enable/disable custom buttons
    /// </summary>
    private void METEnableCustomBtn()
    {
        SalesTable salesTable = this.cursor() as SalesTable;
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCancellation))).enabled(salesTable.SalesStatus == SalesStatus::Canceled);
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCreation))).enabled((salesTable.SalesStatus != SalesStatus::Canceled)&&
                                            (salesTable.DocumentStatus == DocumentStatus::None || salesTable.DocumentStatus == DocumentStatus::Confirmation) &&
                                            (salesTable.METOrderExtractStatus != METOrderExtractStatus::Extracted));
        //CB625_TMSSOPickingListExtraction access to the button
        MetSalesTable   metSalesTableLoc = METSalesTable::findByRefRecId(salesTable.RecId);
        InventLocation  inventLocationLoc = InventLocation::find(salesTable.InventLocationId);
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderPickingList))).enabled(salesTable.SalesStatus != SalesStatus::Canceled
                                                && !metSalesTableLoc.InternalCrossDockOrder && !inventLocationLoc.METCSDWarehouse
                                                && salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted);

    }
